+/*
+ * vs_eth_stats.c
+ *
+ * Copyright 2025 VertexCom, ShanTon Tu <shanton.tu@vertexcom.com>
+ *
+ * Wireshark - Network traffic analyzer
+ * By Gerald Combs <gerald@wireshark.org>
+ * Copyright 1998 Gerald Combs
+ *
+ * SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#include <epan/ptvcursor.h>
+
+#include "plugins/epan/homeplug-av/vendor/spidcom/common_values.h"
+#include "plugins/epan/homeplug-av/vendor/spidcom/dissect_vs.h"
+#include "plugins/epan/homeplug-av/vendor/spidcom/marco.h"
+
+/* VS_ETH_STATS.REQ (0xA024)
+Fields:
+- Command (1 byte): 0x00 = Get statistics, 0x01 = Reset statistics
+*/
+
+/* VS_ETH_STATS.CNF (0xA025)
+Fields:
+- Result (1 byte): 0x00 = Success, 0x01 = Failure
+- Rx packets (4 bytes): Number of packets received
+- Rx good packets (4 bytes): Number of packets received without error
+- Rx unicast (4 bytes): Number of unicast packets received without error
+- Rx multicast (4 bytes): Number of multicast packets received without error
+- Rx broadcast (4 bytes): Number of broadcast packets received without error
+- Rx errors (4 bytes): Number of packets received with error
+- Rx FIFO overflow (4 bytes): Number of packets dropped due to Rx FIFO overflow
+(note: not counted as received packets)
+- Tx packets (4 bytes): Number of packets transmitted
+- Tx good packets (4 bytes): Number of packets transmitted without error
+- Tx unicast (4 bytes): Number of unicast packets transmitted without error
+- Tx multicast (4 bytes): Number of multicast packets transmitted without error
+- Tx broadcast (4 bytes): Number of broadcast packets transmitted without error
+- Tx errors (4 bytes): Number of packets transmitted with error
+- Tx fifo underflow (4 bytes): Number of packets dropped due to Tx FIFO
+underflow
+- Tx collisions (4 bytes): Number of packets with transmit error due to a
+collision on medium
+- Tx carrier error (4 bytes): Number of packets aborted due to carrier sense
+error
+*/
+
+static int ett_vs_eth_stats_req;
+static int hf_vs_eth_stats_req;
+static int hf_vs_eth_stats_req_command;
+
+static int ett_vs_eth_stats_cnf;
+static int hf_vs_eth_stats_cnf;
+static int hf_vs_eth_stats_cnf_result;
+static int hf_vs_eth_stats_cnf_rx_packets;
+static int hf_vs_eth_stats_cnf_rx_good_packets;
+static int hf_vs_eth_stats_cnf_rx_unicast;
+static int hf_vs_eth_stats_cnf_rx_multicast;
+static int hf_vs_eth_stats_cnf_rx_broadcast;
+static int hf_vs_eth_stats_cnf_rx_errors;
+static int hf_vs_eth_stats_cnf_rx_fifo_overflow;
+static int hf_vs_eth_stats_cnf_tx_packets;
+static int hf_vs_eth_stats_cnf_tx_good_packets;
+static int hf_vs_eth_stats_cnf_tx_unicast;
+static int hf_vs_eth_stats_cnf_tx_multicast;
+static int hf_vs_eth_stats_cnf_tx_broadcast;
+static int hf_vs_eth_stats_cnf_tx_errors;
+static int hf_vs_eth_stats_cnf_tx_fifo_underflow;
+static int hf_vs_eth_stats_cnf_tx_collisions;
+static int hf_vs_eth_stats_cnf_tx_carrier_errors;
+
+static bool dissect_vs_eth_stats_req(tvbuff_t *tvb, packet_info *pinfo,
+                                     proto_tree *tree, void *data) {
+    homeplug_av_vendor_context_t *ctx;
+    ptvcursor_t *cursor;
+    ctx = (homeplug_av_vendor_context_t *)data;
+    DISSECTOR_ASSERT(ctx);
+
+    if (ctx->mmtype != HOMEPLUG_AV_MMTYPE_SPIDCOM_VS_ETH_STATS_REQ) {
+        return false;
+    }
+
+    cursor = ptvcursor_new(pinfo->pool, tree, tvb, 0);
+    ptvcursor_advance(cursor, 3);  // shift after OUI bytes
+
+    ADD_SPIDCOM_MMTYPE_SUBTREE(cursor, vs, eth_stats_req);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 1, ENC_NA, vs, eth_stats_req, command);
+
+    ptvcursor_pop_subtree(cursor);
+
+    return true;
+}
+
+static bool dissect_vs_eth_stats_cnf(tvbuff_t *tvb, packet_info *pinfo,
+                                     proto_tree *tree, void *data) {
+    homeplug_av_vendor_context_t *ctx;
+    ptvcursor_t *cursor;
+    ctx = (homeplug_av_vendor_context_t *)data;
+    DISSECTOR_ASSERT(ctx);
+
+    if (ctx->mmtype != HOMEPLUG_AV_MMTYPE_SPIDCOM_VS_ETH_STATS_CNF) {
+        return false;
+    }
+
+    cursor = ptvcursor_new(pinfo->pool, tree, tvb, 0);
+    ptvcursor_advance(cursor, 3);  // shift after OUI bytes
+
+    ADD_SPIDCOM_MMTYPE_SUBTREE(cursor, vs, eth_stats_cnf);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 1, ENC_NA, vs, eth_stats_cnf, result);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               rx_packets);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               rx_good_packets);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               rx_unicast);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               rx_multicast);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               rx_broadcast);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               rx_errors);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               rx_fifo_overflow);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               tx_packets);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               tx_good_packets);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               tx_unicast);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               tx_multicast);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               tx_broadcast);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               tx_errors);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               tx_fifo_underflow);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               tx_collisions);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, eth_stats_cnf,
+                               tx_carrier_errors);
+
+    ptvcursor_pop_subtree(cursor);
+
+    return true;
+}
+
+void register_spidcom_mmtype_vs_eth_stats(int proto) {
+    static hf_register_info hf[] = {
+        REG_SPIDCOM_MMENTRY(VS_ETH_STATS.REQ, vs, eth_stats_req),
+        REG_SPIDCOM_MMTYPE_FIELD("Command", FT_UINT8, BASE_HEX,
+                                   VALS(spidcom_val_str_stats_command), 0x0,
+                                   NULL, vs, eth_stats_req, command),
+        REG_SPIDCOM_MMENTRY(VS_ETH_STATS.CNF, vs, eth_stats_cnf),
+        REG_SPIDCOM_MMTYPE_FIELD("Result", FT_UINT8, BASE_HEX,
+                                   VALS(spidcom_val_str_result), 0x0, NULL,
+                                   vs, eth_stats_cnf, result),
+        REG_SPIDCOM_MMTYPE_FIELD("Rx Packets", FT_UINT32, BASE_DEC, NULL, 0x0,
+                                   "Number of Rx packets", vs, eth_stats_cnf,
+                                   rx_packets),
+        REG_SPIDCOM_MMTYPE_FIELD("Rx Good Packets", FT_UINT32, BASE_DEC, NULL,
+                                   0x0, "Number of Rx good packets", vs,
+                                   eth_stats_cnf, rx_good_packets),
+        REG_SPIDCOM_MMTYPE_FIELD("Rx Unicast", FT_UINT32, BASE_DEC, NULL, 0x0,
+                                   "Number of Rx unicast", vs, eth_stats_cnf,
+                                   rx_unicast),
+        REG_SPIDCOM_MMTYPE_FIELD("Rx Multicast", FT_UINT32, BASE_DEC, NULL,
+                                   0x0, "Number of Rx multicast", vs,
+                                   eth_stats_cnf, rx_multicast),
+        REG_SPIDCOM_MMTYPE_FIELD("Rx Broadcast", FT_UINT32, BASE_DEC, NULL,
+                                   0x0, "Number of Rx broadcast", vs,
+                                   eth_stats_cnf, rx_broadcast),
+        REG_SPIDCOM_MMTYPE_FIELD("Rx Errors", FT_UINT32, BASE_DEC, NULL, 0x0,
+                                   "Number of Rx errors", vs, eth_stats_cnf,
+                                   rx_errors),
+        REG_SPIDCOM_MMTYPE_FIELD("Rx FIFO Overflow", FT_UINT32, BASE_DEC,
+                                   NULL, 0x0, "Number of Rx FIFO overflow", vs,
+                                   eth_stats_cnf, rx_fifo_overflow),
+        REG_SPIDCOM_MMTYPE_FIELD("Tx Packets", FT_UINT32, BASE_DEC, NULL, 0x0,
+                                   "Number of Tx packets", vs, eth_stats_cnf,
+                                   tx_packets),
+        REG_SPIDCOM_MMTYPE_FIELD("Tx Good Packets", FT_UINT32, BASE_DEC, NULL,
+                                   0x0, "Number of Tx good packets", vs,
+                                   eth_stats_cnf, tx_good_packets),
+        REG_SPIDCOM_MMTYPE_FIELD("Tx Unicast", FT_UINT32, BASE_DEC, NULL, 0x0,
+                                   "Number of Tx unicast", vs, eth_stats_cnf,
+                                   tx_unicast),
+        REG_SPIDCOM_MMTYPE_FIELD("Tx Multicast", FT_UINT32, BASE_DEC, NULL,
+                                   0x0, "Number of Tx multicast", vs,
+                                   eth_stats_cnf, tx_multicast),
+        REG_SPIDCOM_MMTYPE_FIELD("Tx Broadcast", FT_UINT32, BASE_DEC, NULL,
+                                   0x0, "Number of Tx broadcast", vs,
+                                   eth_stats_cnf, tx_broadcast),
+        REG_SPIDCOM_MMTYPE_FIELD("Tx Errors", FT_UINT32, BASE_DEC, NULL, 0x0,
+                                   "Number of Tx errors", vs, eth_stats_cnf,
+                                   tx_errors),
+        REG_SPIDCOM_MMTYPE_FIELD("Tx FIFO Underflow", FT_UINT32, BASE_DEC,
+                                   NULL, 0x0, "Number of Tx FIFO underflow", vs,
+                                   eth_stats_cnf, tx_fifo_underflow),
+        REG_SPIDCOM_MMTYPE_FIELD("Tx Collisions", FT_UINT32, BASE_DEC, NULL,
+                                   0x0, "Number of Tx collisions", vs,
+                                   eth_stats_cnf, tx_collisions),
+        REG_SPIDCOM_MMTYPE_FIELD("Tx Carrier Errors", FT_UINT32, BASE_DEC,
+                                   NULL, 0x0, "Number of Tx carrier errors", vs,
+                                   eth_stats_cnf, tx_carrier_errors)};
+
+    static int *ett[] = {&ett_vs_eth_stats_req, &ett_vs_eth_stats_cnf};
+
+    proto_register_field_array(proto, hf, array_length(hf));
+    proto_register_subtree_array(ett, array_length(ett));
+
+    REG_SPIDCOM_MMTYPE_DISSECTOR(VS_ETH_STATS.REQ, proto, vs, eth_stats_req);
+    REG_SPIDCOM_MMTYPE_DISSECTOR(VS_ETH_STATS.CNF, proto, vs, eth_stats_cnf);
+}

