+
+#include <epan/ptvcursor.h>
+
+#include "plugins/epan/homeplug-av/vendor/spidcom/common_values.h"
+#include "plugins/epan/homeplug-av/vendor/spidcom/dissect_vs.h"
+#include "plugins/epan/homeplug-av/vendor/spidcom/marco.h"
+
+/* VS_FILE_ACCESS.REQ (0xA4FC)
+Fields:
+- OPcode (1 byte):
+  - 0x00 = Write
+  - 0x01 = Read
+  - 0x02 = Delete
+  - 0x03 = List directory
+  - 0x04 = Make directory
+  - 0x05 = Delete directory
+  - 0x06 = Format flash
+  - 0x07 = Save
+  - 0x08 = Scan STA
+- FileType (1 byte):
+  - 0x00 = Bootloader
+  - 0x01 = Simage
+  - 0x02 = All other files
+  - 0x03 = Debug trace
+  - 0x04-0xff = Reserved
+- Parameter (32 bytes): ASCII string of filename and path in file system
+- Total Fragments (2 bytes): Number of total fragments
+- Fragment Sequence Number (2 bytes): Sequence number of this fragment
+- Offset (4 bytes): The byte offset from start of the file
+- Checksum (4 bytes): Checksum value to verify data integrity
+- Length (2 bytes): The byte length of the fragment
+- Data (variable): The data of the fragment
+*/
+
+/* VS_FILE_ACCESS.CNF (0xA4FD)
+Fields:
+- Status (1 byte):
+  - 0x00 = Success
+  - 0x01 = Failure
