+static bool dissect_vs_spi_stats_req(tvbuff_t *tvb, packet_info *pinfo,
+                                     proto_tree *tree, void *data) {
+    homeplug_av_vendor_context_t *ctx;
+    ptvcursor_t *cursor;
+    ctx = (homeplug_av_vendor_context_t *)data;
+    DISSECTOR_ASSERT(ctx);
+
+    if (ctx->mmtype != HOMEPLUG_AV_MMTYPE_SPIDCOM_VS_SPI_STATS_REQ) {
+        return false;
+    }
+
+    cursor = ptvcursor_new(pinfo->pool, tree, tvb, 0);
+    ptvcursor_advance(cursor, 3);  // shift after OUI bytes
+
+    ADD_SPIDCOM_MMTYPE_SUBTREE(cursor, vs, spi_stats_req);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 1, ENC_NA, vs, spi_stats_req, command);
+
+    ptvcursor_pop_subtree(cursor);
+
+    return true;
+}
