+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, spi_stats_cnf,
+                               rx_command_fail);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, spi_stats_cnf,
+                               rx_unknown_command);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, spi_stats_cnf,
+                               rx_data_dft_error);
+    ADD_SPIDCOM_MMTYPE_FIELD(cursor, 4, ENC_LITTLE_ENDIAN, vs, spi_stats_cnf,
